with recent_employees as (select * from employees where manager_id is null), summary as (select month(hire_date) as hire_month, year(hire_date) as hire_year, round(stddev(salary), 2) as stddev_salary, max(salary) - min(salary) as salary_range from recent_employees group by month(hire_date), year(hire_date)) select hire_month, hire_year, stddev_salary, salary_range from summary where salary_range > 26 order by stddev_salary, hire_year desc;
